#include <unistd.h>
#include <sys/stat.h>
#include <limits.h>
#include <stdio.h>
#include <stdlib.h>

long get_device_id_from_symlink(char *link) {
    char target_path[PATH_MAX];
    ssize_t len = readlink(link, target_path, sizeof(target_path) - 1);

    if (len == -1) {
        perror("Failed to read symbolic link");
        return -1;
    }

    target_path[len] = '\0'; // Null-terminate the string

    struct stat file_stat;
    if (stat(target_path, &file_stat) != 0) {
        perror("Failed to get file status");
        return -1;
    }

    if (S_ISDIR(file_stat.st_mode)) {
        perror("Target is a directory, not a file");
        return -1;
    }

    return (long)file_stat.st_dev;
}

