    ssize_t len = readlink(link, target_path, sizeof(target_path) - 1);

    if (len == -1) {
        return -1;
    }

    target_path[len] = '\0';

    struct stat stat_buf;
    if (stat(target_path, &stat_buf) == -1) {
        return -1;
    }

    return (long) stat_dev(stat_buf);
}

