long get_linked_file_device_id(const char *link) {
    struct stat sb;
    char path[PATH_MAX];

    if (realpath(link, path) == NULL) {
        perror("Failed to resolve symbolic link");
        return -1;
    }

    if (lstat(path, &sb) == -1) {
        perror("lstat");
        return -1;
    }

    return sb.st_dev;
}

